<template>
  <div style="padding: 10px">
    <el-main>

      <div style="font-size: 20px; padding: 10px; font-weight: bold">
        期末考试
      </div>
      <!-- 学生答题防作弊监控提示条 -->
      <div v-if="!isTeacher && antiCheatEnabled" style="padding: 10px; display: flex; gap: 10px; align-items: center; background: #fef0f0; border: 1px solid #f56c6c; border-radius: 4px; margin-bottom: 10px;">
        <el-icon :size="18" color="#f56c6c"><Warning/></el-icon>
        <span style="font-size: 13px; color: #f56c6c; flex: 1;">
          期末考试监控已启用：禁止切换页面/使用插件/截图，每3分钟自动拍摄摄像头照片。违规行为将被记录。
        </span>
        <el-tag :type="snapshotUploading ? 'warning' : 'success'" size="small">
          {{ snapshotUploading ? '上传中' : '监控中' }}
        </el-tag>
        <span style="font-size: 12px; color: #909399;">
          下次拍照: {{ nextSnapshotCountdown }}
        </span>
      </div>
      <div v-show="isTeacher" style="font-size: 15px; padding: 10px;">
        <div style="padding: 10px; font-size: 14px">
          <!--   遍历 examList-->
          <div v-if="examList !== null">
            <div v-for="(item,index) in examList" :key="index">
              <!--            根据item.question_type 是否为0 来动态展示不同的组件-->
              <el-tag v-if="item.question_type === '0'" type="primary">单选</el-tag>
              <el-tag v-if="item.question_type === '1'" type="success">判断</el-tag>
              <!--            显示富文本-->
              <span v-html="item.question" style="padding: 10px"></span>
              <div style="padding: 10px" v-if="item.question_type === '0'">
                <el-radio-group v-model="user_answer[index]" size="mini"
                                style="display: flex;flex-flow: column nowrap;align-items: flex-start;">
                  <el-radio label="A" border style="margin-left: 40px; margin-top: 10px">{{ item.option1 }}</el-radio>
                  <el-radio label="B" border style="margin-left: 40px; margin-top: 10px">{{ item.option2 }}</el-radio>
                  <el-radio label="C" border style="margin-left: 40px; margin-top: 10px">{{ item.option3 }}
                  </el-radio>
                  <el-radio label="D" border style="margin-left: 40px; margin-top: 10px">{{ item.option4 }}</el-radio>
                </el-radio-group>
              </div>
              <div style="padding: 10px" v-if="item.question_type === '1'">
                <el-radio-group v-model="user_answer[index]" size="mini"
                                style="display: flex;flex-flow: column nowrap;align-items: flex-start;">
                  <el-radio label="A" border style="margin-left: 40px; margin-top: 10px">{{ item.option1 }}</el-radio>
                  <el-radio label="B" border style="margin-left: 40px; margin-top: 10px">{{ item.option2 }}</el-radio>
                </el-radio-group>
              </div>
              <div style="padding: 20px; color: #00CC7E" v-show="isTeacher">
                正确答案： {{ item.correct_answer }} <br>
                答案解析： {{ item.answer_analy }}
              </div>
            </div>
            <!--          选择完章节和小节后才可以 看到按钮-->
            <!--            <div style="padding: 40px; display: flex" v-show="showTestButton">-->
            <!--              <el-button type="success" @click="submitTest">提交答案</el-button>-->
            <!--              <el-button type="primary" @click="reTest">重做一遍</el-button>-->
            <!--            </div>-->
          </div>
          <div v-else>
            暂无数据
          </div>
        </div>
      </div>
      <div v-show="!isTeacher" style="font-size: 15px; padding: 10px; color: #A6A6AE">
        <div style="display: flex">
          <el-icon :size="40">
            <WarningFilled/>
          </el-icon>
          <div style="padding: 10px">期末考试还未开放！
          </div>
        </div>
      </div>
      <el-divider></el-divider>
    </el-main>
  </div>
</template>

<script>
import AsideVue from "@/components/AsideVue.vue";

import chat22232 from "@/assets/image/teacher/2223-2.png";
import chat22233 from "@/assets/image/teacher/2223-3.png";
import chat22234 from "@/assets/image/teacher/2223-4.png";
import chat24252 from "@/assets/image/teacher/2425-4.png";
import chat24254 from "@/assets/image/teacher/2425-4.png";
import {ArrowLeft, ArrowRight, Search, Warning, WarningFilled} from "@element-plus/icons-vue";
import * as echarts from "echarts";
import axios from "axios";

// eslint-disable-next-line vue/no-export-in-script-setup
export default {
  name: "FinTest",
  components: {
    AsideVue,
  },
  data() {
    return {
      isTeacher: false,
      examList: [],
      user_answer: [],
      // === 防作弊相关 ===
      antiCheatEnabled: false,
      mediaStream: null,
      snapshotTimer: null,
      snapshotCountdownTimer: null,
      nextSnapshotSeconds: 180,
      snapshotUploading: false,
      violationCount: 0,
      //
    }
  },
  created() {
    //   判断是否是老师
    this.isTeacher = localStorage.getItem('username') === 'admin'
    this.getExamList()
    // 学生进入期末考试页面时立即启用防作弊监控
    if (!this.isTeacher) {
      this.$nextTick(() => this.startAntiCheat());
    }
  },
  computed: {
    username() {
      return localStorage.getItem('username') || '';
    },
    nextSnapshotCountdown() {
      const m = Math.floor(this.nextSnapshotSeconds / 60);
      const s = this.nextSnapshotSeconds % 60;
      return `${m}:${s.toString().padStart(2, '0')}`;
    }
  },
  beforeUnmount() {
    this.stopAntiCheat();
  },
  methods: {
    // ============ 防作弊相关 ============
    async startAntiCheat() {
      if (this.isTeacher) return;
      if (this.antiCheatEnabled) return;
      try {
        this.mediaStream = await navigator.mediaDevices.getUserMedia({
          video: { width: 640, height: 480 },
          audio: false
        });
      } catch (err) {
        console.error('摄像头权限获取失败:', err);
        this.$message.error('无法访问摄像头，期末考试监控无法启用。');
        return;
      }
      this.antiCheatEnabled = true;
      this.violationCount = 0;
      document.addEventListener('visibilitychange', this.handleVisibilityChange);
      window.addEventListener('blur', this.handleWindowBlur);
      document.addEventListener('mouseleave', this.handleMouseLeave);
      document.addEventListener('contextmenu', this.disableContextMenu);
      document.addEventListener('keydown', this.handleKeydown);
      document.addEventListener('dragstart', this.disableDrag);
      this.startSnapshotSchedule();
      this.captureAndUploadSnapshot();
      this.$message.success('期末考试监控已启用，请勿离开页面或使用作弊插件。');
    },
    stopAntiCheat() {
      if (!this.antiCheatEnabled) return;
      this.antiCheatEnabled = false;
      if (this.snapshotTimer) { clearInterval(this.snapshotTimer); this.snapshotTimer = null; }
      if (this.snapshotCountdownTimer) { clearInterval(this.snapshotCountdownTimer); this.snapshotCountdownTimer = null; }
      document.removeEventListener('visibilitychange', this.handleVisibilityChange);
      window.removeEventListener('blur', this.handleWindowBlur);
      document.removeEventListener('mouseleave', this.handleMouseLeave);
      document.removeEventListener('contextmenu', this.disableContextMenu);
      document.removeEventListener('keydown', this.handleKeydown);
      document.removeEventListener('dragstart', this.disableDrag);
      if (this.mediaStream) {
        this.mediaStream.getTracks().forEach(track => track.stop());
        this.mediaStream = null;
      }
    },
    startSnapshotSchedule() {
      this.nextSnapshotSeconds = 180;
      if (this.snapshotCountdownTimer) clearInterval(this.snapshotCountdownTimer);
      this.snapshotCountdownTimer = setInterval(() => {
        if (this.nextSnapshotSeconds > 0) this.nextSnapshotSeconds--;
      }, 1000);
      if (this.snapshotTimer) clearInterval(this.snapshotTimer);
      this.snapshotTimer = setInterval(() => {
        this.captureAndUploadSnapshot();
        this.nextSnapshotSeconds = 180;
      }, 3 * 60 * 1000);
    },
    captureAndUploadSnapshot() {
      if (!this.mediaStream) return;
      try {
        const video = document.createElement('video');
        video.srcObject = this.mediaStream;
        video.play();
        video.addEventListener('loadeddata', () => {
          const canvas = document.createElement('canvas');
          canvas.width = 640;
          canvas.height = 480;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(video, 0, 0, 640, 480);
          canvas.toBlob((blob) => {
            if (blob) this.uploadSnapshot(blob);
          }, 'image/jpeg', 0.8);
        }, { once: true });
      } catch (err) {
        console.error('截图失败:', err);
      }
    },
    async uploadSnapshot(blob) {
      if (this.snapshotUploading) return;
      this.snapshotUploading = true;
      const formData = new FormData();
      formData.append('image', blob, 'snapshot.jpg');
      formData.append('username', this.username);
      formData.append('chapter', '9');
      formData.append('subchapter', '9');
      try {
        await axios.post('/api/uploadExamSnapshot', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
      } catch (err) {
        console.error('上传期末考试截图失败:', err);
      } finally {
        this.snapshotUploading = false;
      }
    },
    handleVisibilityChange() {
      if (document.hidden && this.antiCheatEnabled) {
        this.violationCount++;
        this.reportExamViolation('page_hidden', '期末考试期间切换或隐藏了当前页面');
        this.$message.error(`检测到离开考试页面！违规次数：${this.violationCount}`);
      }
    },
    handleWindowBlur() {
      if (this.antiCheatEnabled) {
        this.violationCount++;
        this.reportExamViolation('window_blur', '期末考试窗口失去焦点');
        this.$message.warning(`检测到窗口失焦！违规次数：${this.violationCount}`);
      }
    },
    handleMouseLeave(e) {
      if (this.antiCheatEnabled && (e.clientY <= 0 || e.clientX <= 0 || e.clientX >= window.innerWidth || e.clientY >= window.innerHeight)) {
        this.violationCount++;
        this.reportExamViolation('mouse_leave', '鼠标离开期末考试页面可视区域');
        this.$message.warning(`检测到鼠标离开考试区域！违规次数：${this.violationCount}`);
      }
    },
    disableContextMenu(e) {
      if (this.antiCheatEnabled) {
        e.preventDefault();
        this.reportExamViolation('context_menu', '期末考试期间尝试打开右键菜单');
        this.$message.warning('考试期间禁止右键操作');
      }
    },
    disableDrag(e) {
      if (this.antiCheatEnabled) e.preventDefault();
    },
    handleKeydown(e) {
      if (!this.antiCheatEnabled) return;
      const key = e.key ? e.key.toLowerCase() : '';
      const ctrl = e.ctrlKey || e.metaKey;
      if (key === 'printscreen') {
        this.violationCount++;
        this.reportExamViolation('screenshot_key', '检测到 PrintScreen 截屏按键');
        this.$message.error(`检测到截屏操作！违规次数：${this.violationCount}`);
        e.preventDefault();
        return;
      }
      if (ctrl && ['p', 's', 'c', 'v', 'x', 'a'].includes(key)) {
        this.reportExamViolation('forbidden_shortcut', `检测到受限快捷键 Ctrl/Cmd+${key.toUpperCase()}`);
        this.$message.warning('考试期间禁止复制/粘贴/打印/保存');
        e.preventDefault();
        return;
      }
      if (key === 'f12' || (ctrl && e.shiftKey && ['i', 'j', 'c'].includes(key))) {
        this.reportExamViolation('developer_tools', '检测到尝试打开开发者工具');
        this.$message.warning('考试期间禁止开发者工具');
        e.preventDefault();
      }
    },
    reportExamViolation(eventType, eventDetail) {
      axios.post('/api/exam/behavior/event', {
        username: this.username,
        chapter: '9',
        subchapter: '9',
        eventType,
        eventDetail
      }).catch(err => console.error('上报期末考试异常失败:', err));
    },
    //
    async getExamList() {
      const data = {
        chapter: '9',
        subchapter: '9',
      };
      await axios.post('/api/exam', data)
          .then(response => {
            console.log("fanhui" + response.data)
            // examList 转为JSON数据
            this.examList = response.data
            // this.examList 的类型
          })
    },


  }
}
</script>

